            view = self._dispatch_takeover_view(dispatch_id, adapter_id)
            self._emit(
                wallet_id,
                self._audit_event(
                    audit.TYPE_CHAIN_DISPATCH_TAKEN_OVER,
                    request_id=dispatch_id,
                    actor_id=approval_request_id,
                    reason=None,
                    details=view,
                ),
            )
            return 201, view
    except CorruptDataError:
        raise
    except ValueError:
